      padding: 0 16px;
      background-color: #e5e7eb;
      border: none;
      border-radius: var(--radius);
      font-family: inherit;
      font-size: 14px;
      font-weight: 600;
      color: var(--text-main);
      cursor: pointer;
      transition: background-color 0.2s;
